import { HumanMessage } from "@langchain/core/messages";
import { Annotation, StateGraph } from "@langchain/langgraph";
import { Query, Compiler } from "../agents/compiler";
import { GPT4o } from "../models";

const openAIKey = process.env.API_OPENAI_API_KEY;
/**
 * An instance of the GPT-4o language model configured with the provided OpenAI API key and a temperature of 0.
 *
 * @remarks
 * The temperature parameter controls the randomness of the model's output. A value of 0 makes the output more deterministic.
 *
 * @see {@link https://platform.openai.com/docs/guides/text-generation}
 */
const llm = GPT4o({ apiKey: openAIKey, temperature: 0 });

/**
 * Represents the root state of the AI graph, encapsulating all relevant properties
 * for managing the conversation and its persistence.
 *
 * @property query - The current query object being processed.
 * @property messages - An array of base messages exchanged in the conversation.
 * @property persisted - Indicates whether the current state has been persisted.
 * @property userInput - The latest input provided by the user.
 * @property assistant - The latest response generated by the assistant.
 * @property finish - Flag indicating whether the conversation has finished.
 */
const IntentState = Annotation.Root({
  query: Annotation<typeof Query>,
  userInput: Annotation<string>,
  finish: Annotation<boolean>,
});

/**
 * Executes an expert node in the graph by compiling a query using the provided state.
 *
 * This function creates a new `Compiler` instance with the specified language model (`llm`) and query type (`Query`).
 * It then constructs a `HumanMessage` from the user's input in the state, and calls the expert to process the message.
 * The result is returned as an object containing the generated query and a `finish` flag set to `true`.
 *
 * @param state - The current graph state containing user input and other relevant data.
 * @returns An object with the generated query and a finish flag.
 */
const expertNode = async (state: typeof IntentState.State) => {
  const expert = new Compiler(llm, Query);
  const message = new HumanMessage(state.userInput);
  const query = await expert.call([message]);
  return { query: query, finish: true };
};

export const IntentDiscoveryGraph = (config: any = {}) => {
  return new StateGraph(IntentState)
    .addNode("expert_node", expertNode)
    .addEdge("__start__", "expert_node")
    .addEdge("expert_node", "__end__")
    .compile(config);
};

export type IntentDiscoveryGraphType = ReturnType<typeof IntentDiscoveryGraph>;
